const data = $json;
const message = data.message || {};
const callback = data.callback_query || {};

const chat_id = message.chat?.id || callback.message?.chat?.id || null;
const telegram_id = message.from?.id || callback.from?.id || null;
const first_name = message.from?.first_name || callback.from?.first_name || 'Telegram Customer';
const message_text = (message.text || '').trim();
const callback_data = callback.data || '';

let intent = 'other';
let product_id = 0;

// add_101 / edit_101 / remove_101
const m = callback_data.match(/^(add|edit|remove)_(\d+)$/);
if (m) product_id = Number(m[2]);

if (callback_data) {
  if (callback_data === 'place_order' || callback_data === 'start_order') intent = 'start_order';
  else if (callback_data === 'show_products' || callback_data === 'add_more') intent = 'show_products';
  else if (callback_data === 'search_product') intent = 'search_prompt';
  else if (callback_data === 'view_cart') intent = 'view_cart';
  else if (callback_data === 'checkout') intent = 'checkout';
  else if (callback_data === 'submit_order') intent = 'submit_order';
  else if (callback_data === 'order_yes') intent = 'confirmation_yes';
  else if (callback_data === 'order_no') intent = 'confirmation_no';
  else if (callback_data === 'change_address') intent = 'change_address';
  else if (callback_data === 'noop') intent = 'noop';
  else if (m && m[1] === 'add') intent = 'add_to_cart';
  else if (m && m[1] === 'edit') intent = 'edit_quantity';
  else if (m && m[1] === 'remove') intent = 'remove_item';
} else if (message_text) {
  intent = 'customer_message';
}

return {
  json: {
    chat_id,
    telegram_id,
    first_name,
    message_text,
    callback_data,
    callback_query_id: callback.id || null,
    intent,
    product_id
  }
};

// Decides the final intent. Text messages depend on what the bot is waiting for
// (pending_order.awaiting: search | qty:<product_id> | address).
const n = $('Normalize Input').first().json;
const s = $input.first()?.json || {};
const awaiting = s.awaiting || '';

// Burmese digits -> ASCII digits
const toAscii = (t) => t.replace(/[၀-၉]/g, (d) => '၀၁၂၃၄၅၆၇၈၉'.indexOf(d));

let intent = n.intent;
let product_id = n.product_id || 0;
let quantity = 0;
let search_term = '';
let delivery_address = '';
let note = '';

// "Change Address" button: always ask for the address again
if (intent === 'change_address') { intent = 'checkout'; note = 'change'; }

if (intent === 'customer_message') {
  const text = n.message_text;
  const lower = text.toLowerCase();

  if (/^\/(start|menu)\b/.test(lower) ||
      /^(hi|hello|hey|good (morning|evening|afternoon)|mingalaba|မင်္ဂလာပါ)(\s|[!.,]|$)/i.test(text)) {
    intent = 'greeting';
  } else if (/^\/cart\b/.test(lower)) {
    intent = 'view_cart';
  } else if (/^\/products\b/.test(lower)) {
    intent = 'show_products';
  } else if (/^\/search\b/.test(lower)) {
    const q = text.replace(/^\/search\s*/i, '').trim();
    if (q) { intent = 'search_input'; search_term = q; } else { intent = 'search_prompt'; }
  } else if (awaiting === 'search') {
    intent = 'search_input';
    search_term = text;
  } else if (awaiting.startsWith('qty:')) {
    product_id = Number(awaiting.split(':')[1]) || 0;
    const q = toAscii(text).trim();
    if (/^\d{1,3}$/.test(q)) { intent = 'qty_input'; quantity = Number(q); }
    else { intent = 'edit_quantity'; note = 'invalid'; }
  } else if (awaiting === 'address') {
    if (text.length >= 5) { intent = 'address_input'; delivery_address = text.slice(0, 500); }
    else { intent = 'checkout'; note = 'invalid'; }
  } else {
    intent = 'ai_text';
  }
}

return [{
  json: {
    chat_id: n.chat_id,
    telegram_id: n.telegram_id,
    first_name: n.first_name,
    message_text: n.message_text,
    callback_data: n.callback_data,
    callback_query_id: n.callback_query_id,
    intent,
    product_id,
    quantity,
    search_term,
    delivery_address,
    note,
    awaiting,
    cart_status: s.cart_status || ''
  }
}];

// ---- settings ----
const ENFORCE_STOCK = false;   // true  => products with stock <= 0 cannot be added to the cart
const MAX_ITEMS = 8;           // max product cards per message batch
// ------------------
const route = $('Route Intent').first().json;
const chat_id = route.chat_id;

const num = (v) => { const x = Number(v); return isFinite(x) ? x : 0; };
const fmt = (v) => num(v).toLocaleString('en-US', { maximumFractionDigits: 2 });

// /search_products -> { data: [...] }   /products?search= -> { found, products: [...] }
const all = $input.all().map((i) => i.json);
let list = [];
if (all.length === 1 && Array.isArray(all[0].data)) list = all[0].data;
else if (all.length === 1 && Array.isArray(all[0].products)) list = all[0].products;
else if (all.length >= 1 && all[0] && all[0].id !== undefined) list = all;

const products = list
  .map((p) => ({
    id: Number(p.id),
    name: p.name || p.display_name || 'Product',
    code: p.default_code || p.code || '',
    price: num(p.price ?? p.list_price),
    currency: p.currency || '',
    stock: (p.stock ?? p.qty_available ?? null)
  }))
  .filter((p) => p.id)
  .slice(0, MAX_ITEMS);

if (!products.length) {
  const term = route.search_term ? ` for "${route.search_term}"` : '';
  return [{ json: {
    chat_id,
    text: `😔 No products found${term}.\nTry another name or product code.`,
    button_text: '🔍 Search Product',
    button_cb: 'search_product',
    cache: null
  } }];
}

return products.map((p) => {
  const stockKnown = p.stock !== null && p.stock !== undefined && p.stock !== '';
  const canAdd = !ENFORCE_STOCK || !stockKnown || num(p.stock) > 0;
  let text = `📦 ${p.name}`;
  if (p.code) text += `\nCode: ${p.code}`;
  text += `\nPrice: ${fmt(p.price)} ${p.currency}`.trimEnd();
  if (stockKnown) text += `\nStock: ${fmt(p.stock)}`;
  return { json: {
    chat_id,
    text,
    button_text: canAdd ? '➕ Add to Cart' : '❌ Out of Stock',
    button_cb: canAdd ? `add_${p.id}` : 'noop',
    cache: { id: p.id, name: p.name, code: p.code, price: p.price, currency: p.currency, stock: stockKnown ? num(p.stock) : null }
  } };
});

const route = $('Route Intent').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r.product_id);
const num = (v) => { const x = Number(v); return isFinite(x) ? x : 0; };
const fmt = (v) => num(v).toLocaleString('en-US', { maximumFractionDigits: 2 });

if (!rows.length) return [{ json: { chat_id: route.chat_id, empty: true } }];

const currency = rows[0].currency || '';
const total = rows.reduce((s, r) => s + num(r.quantity) * num(r.price), 0);
const summary = `🛒 Your Shopping Cart\nItems: ${rows.length}\nTotal: ${fmt(total)} ${currency}`.trimEnd();

return rows.map((r, i) => ({ json: {
  chat_id: route.chat_id,
  empty: false,
  product_id: r.product_id,
  text: `${i + 1}. ${r.product_name}\nQty: ${fmt(r.quantity)} × ${fmt(r.price)} = ${fmt(num(r.quantity) * num(r.price))} ${r.currency || ''}`.trimEnd(),
  summary
} }));

const route = $('Route Intent').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r.product_name);
const num = (v) => { const x = Number(v); return isFinite(x) ? x : 0; };
const fmt = (v) => num(v).toLocaleString('en-US', { maximumFractionDigits: 2 });

if (!rows.length) {
  return [{ json: { chat_id: route.chat_id, text: '🛒 Your cart is empty.\n\nSend /products to start shopping.' } }];
}
const currency = rows[0].currency || '';
const total = rows.reduce((s, r) => s + num(r.quantity) * num(r.price), 0);
const lines = rows.map((r, i) =>
  `${i + 1}. ${r.product_name} — ${fmt(r.quantity)} × ${fmt(r.price)} = ${fmt(num(r.quantity) * num(r.price))} ${r.currency || ''}`.trimEnd());

const text = '📋 Order Review\n\n' + lines.join('\n') +
  `\n\nTotal: ${fmt(total)} ${currency}\n📍 Delivery: ${rows[0].delivery_address || '-'}\n\nSubmit this order?`;
return [{ json: { chat_id: route.chat_id, text } }];

const route = $('Route Intent').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r.product_id);
const num = (v) => { const x = Number(v); return isFinite(x) ? x : 0; };

if (!rows.length) {
  return [{ json: {
    ok: false,
    chat_id: route.chat_id,
    text: '⚠️ Nothing to submit.\nYour cart may be empty, the delivery address is missing, or this order was already submitted.\n\nSend /cart to review your cart.'
  } }];
}

const lines = rows.map((r) => ({
  product_id: Number(r.product_id),
  quantity: num(r.quantity),
  price_unit: num(r.price)
}));
const total = lines.reduce((s, l) => s + l.quantity * l.price_unit, 0);

return [{ json: {
  ok: true,
  chat_id: route.chat_id,
  telegram_id: route.telegram_id,
  first_name: route.first_name,
  delivery_address: rows[0].delivery_address,
  lines,
  total,
  currency: rows[0].currency || '',
  item_count: lines.length
} }];

const p = $('Build Payload').first().json;
const r = $input.first()?.json || {};
const d = (r.data && typeof r.data === 'object') ? r.data : r;

const id = d.id || d.quotation_id || d.order_id || null;
const name = d.name || d.quotation_name || d.order_name || '';
const ok = !!id && !r.error && r.success !== false;

const fmt = (v) => Number(v || 0).toLocaleString('en-US', { maximumFractionDigits: 2 });
const total = d.amount_total ?? p.total;
const currency = d.currency || p.currency || '';

const message = `📄 Quotation ${name} (Draft)\nItems: ${p.item_count}\nTotal: ${fmt(total)} ${currency}\n📍 ${p.delivery_address}\n\nPlease confirm your order.`;

return [{ json: {
  ok,
  quotation_id: id,
  quotation_name: name,
  message,
  chat_id: p.chat_id,
  telegram_id: p.telegram_id,
  error: (r.error && (r.error.message || r.error)) || r.message || ''
} }];

const route = $('Route Intent').first().json;
const r = $input.first()?.json || {};
const action = route.intent === 'confirmation_yes' ? 'confirm' : 'cancel';
const ok = r.status === 'submitted' && !!r.quotation_id;

return [{ json: {
  ok,
  action,
  quotation_id: r.quotation_id || null,
  quotation_name: r.quotation_name || '',
  chat_id: route.chat_id,
  telegram_id: route.telegram_id
} }];

