const route = $('Route Intent').first().json;
const raw = $input.first()?.json || {};

function extract(r) {
  const cands = [r.message?.content, r.content, r.output, r.text, r.response];
  for (const c of cands) {
    if (c && typeof c === 'object' && c.intent !== undefined) return c;
    if (typeof c === 'string') {
      const m = c.match(/\{[\s\S]*\}/);
      if (m) { try { return JSON.parse(m[0]); } catch (e) {} }
    }
  }
  return {};
}

const res = extract(raw);
let ai_intent = ['greeting', 'product_search', 'order_request'].includes(res.intent) ? res.intent : 'other';
const term = String(res.product_name || '').trim();

if (ai_intent === 'product_search' || ai_intent === 'order_request') {
  ai_intent = term ? 'product_search' : 'other';
}

return [{ json: { ...route, ai_intent, search_term: term } }];
